import{_ as t,o,c as a,ag as r}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Design Pattern Practice — Production Scenarios","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/deep_dives/PatternSelectionScenarios.md","filePath":"todo/study_plan/deep_dives/PatternSelectionScenarios.md"}'),s={name:"todo/study_plan/deep_dives/PatternSelectionScenarios.md"};function i(n,e,c,l,d,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="design-pattern-practice-—-production-scenarios" tabindex="-1">Design Pattern Practice — Production Scenarios <a class="header-anchor" href="#design-pattern-practice-—-production-scenarios" aria-label="Permalink to &quot;Design Pattern Practice — Production Scenarios&quot;">​</a></h1><blockquote><p><strong>Cross-referenced from:</strong> Part 04 (Design Patterns) rows 7 (Singleton), 8 (Factory Method / Abstract Factory), 9 (Builder), 14 (Strategy). Sister doc to <code>deep_dives/PatternSelectionExercise.md</code> (single-domain &quot;one HR, many factories&quot; mini-project) — this doc is broader (25 scenarios across all creational patterns) and shallower per scenario.</p></blockquote><p>A scenario-based exercise sheet for practising <strong>which pattern fits where</strong> in real-world design. Each scenario is a brief production problem followed by <em>discussion prompts</em> and a <em>suggested approach</em>. Try to answer before reading the suggested approach.</p><p>The goal is not pattern recognition for its own sake — it&#39;s to feel the <strong>trade-off</strong> that makes one pattern fit and another awkward.</p><h2 id="how-to-use-this-doc" tabindex="-1">How to use this doc <a class="header-anchor" href="#how-to-use-this-doc" aria-label="Permalink to &quot;How to use this doc&quot;">​</a></h2><ol><li>Pick a pattern section.</li><li>Read scenario 1&#39;s problem and decision question.</li><li>Spend 2–5 minutes thinking through the prompts before reading the suggested approach.</li><li>The suggested approach is a recommendation, not the only answer — if you reasoned to a different pattern with a clear justification, that&#39;s the actual win.</li><li>Move on to the next scenario.</li></ol><hr><h2 id="singleton" tabindex="-1">Singleton <a class="header-anchor" href="#singleton" aria-label="Permalink to &quot;Singleton&quot;">​</a></h2><h3 id="scenario-1-mdash-application-configuration" tabindex="-1">Scenario 1 — Application configuration <a class="header-anchor" href="#scenario-1-mdash-application-configuration" aria-label="Permalink to &quot;Scenario 1 &amp;mdash; Application configuration&quot;">​</a></h3><p>A web service reads configuration from <code>application.yml</code> at startup and exposes properties (database URL, feature flags, timeouts) to every layer.</p><p><strong>Decision:</strong> how should config be exposed?</p><p><strong>Consider:</strong></p><ul><li>Configuration is identical across the whole process — mutability is undesirable.</li><li>Tests want to swap config in (e.g., point at an in-memory database).</li><li>Many classes need this; passing it through every constructor is tedious.</li></ul><p><strong>Suggested approach:</strong> singleton-scoped bean injected via constructor (Spring or manual DI). The &quot;singleton-ness&quot; is correct; the <em>Singleton pattern as a <code>getInstance()</code> static method</em> is wrong here because it makes the config impossible to swap in tests. <strong>Singleton lifecycle, DI mechanism.</strong></p><h3 id="scenario-2-mdash-per-request-logger" tabindex="-1">Scenario 2 — Per-request logger <a class="header-anchor" href="#scenario-2-mdash-per-request-logger" aria-label="Permalink to &quot;Scenario 2 &amp;mdash; Per-request logger&quot;">​</a></h3><p>Every request handler in a microservice writes log lines tagged with the request ID.</p><p><strong>Decision:</strong> Singleton logger, or something else?</p><p><strong>Consider:</strong></p><ul><li>Log destination (console, file, log aggregation service) is process-global.</li><li>The request ID tag is per-request, not global.</li><li>Loggers compose: each class wants its own logger named after the class.</li></ul><p><strong>Suggested approach:</strong> <strong>not a singleton you write yourself.</strong> SLF4J&#39;s <code>LoggerFactory.getLogger(MyClass.class)</code> is a static factory method that returns a class-specific logger; the underlying logging framework manages process-global state internally. Per-request context is added via <code>MDC</code> (a thread-local), not by holding state on the logger.</p><h3 id="scenario-3-mdash-database-connection-pool" tabindex="-1">Scenario 3 — Database connection pool <a class="header-anchor" href="#scenario-3-mdash-database-connection-pool" aria-label="Permalink to &quot;Scenario 3 &amp;mdash; Database connection pool&quot;">​</a></h3><p>Your app needs to reuse a fixed pool of N database connections across the whole process.</p><p><strong>Decision:</strong> Singleton, or some other shape?</p><p><strong>Consider:</strong></p><ul><li>Only one pool should exist (otherwise N×number-of-pools connections).</li><li>The pool has lifecycle: it must initialise on startup and close on shutdown.</li><li>Tests want to substitute a different pool (in-memory DB, mock).</li></ul><p><strong>Suggested approach:</strong> <strong>DI-managed singleton bean.</strong> Spring&#39;s <code>DataSource</code> bean is the canonical example. The &quot;one instance&quot; guarantee is real, but expressing it as <code>Pool.getInstance()</code> makes lifecycle management awkward (when does it close?). A DI container handles construction, injection, and shutdown via lifecycle hooks.</p><h3 id="scenario-4-mdash-per-user-session" tabindex="-1">Scenario 4 — Per-user session <a class="header-anchor" href="#scenario-4-mdash-per-user-session" aria-label="Permalink to &quot;Scenario 4 &amp;mdash; Per-user session&quot;">​</a></h3><p>A web app keeps user-session data (cart, preferences, recently viewed items) accessible from request handlers.</p><p><strong>Decision:</strong> Singleton, or something else?</p><p><strong>Consider:</strong></p><ul><li>This is <em>per-user</em>, not global.</li><li>Multiple sessions exist concurrently.</li><li>The framework already provides session abstractions.</li></ul><p><strong>Suggested approach:</strong> <strong>not Singleton.</strong> This is a common Singleton trap — &quot;globally accessible&quot; is mistaken for &quot;globally single.&quot; Use the framework&#39;s session abstraction (Spring <code>HttpSession</code>, scoped beans with <code>@SessionScope</code>, etc.) which gives you per-user state with a singleton-like access pattern.</p><h3 id="scenario-5-mdash-unique-id-generator" tabindex="-1">Scenario 5 — Unique ID generator <a class="header-anchor" href="#scenario-5-mdash-unique-id-generator" aria-label="Permalink to &quot;Scenario 5 &amp;mdash; Unique ID generator&quot;">​</a></h3><p>The app needs a process-wide monotonically increasing ID for log correlation.</p><p><strong>Decision:</strong> Singleton fits or not?</p><p><strong>Consider:</strong></p><ul><li>A single counter shared by all callers, otherwise IDs collide.</li><li>High concurrency — thread safety matters.</li><li>Persistence across process restarts may or may not be required.</li></ul><p><strong>Suggested approach:</strong> <strong>singleton lifecycle is correct here</strong>, with <code>AtomicLong</code> for thread safety. Whether you express it as a hand-written Singleton (<code>getInstance()</code>) or a DI-managed bean depends on the surrounding code — the latter is preferred in DI codebases. Across restarts, the &quot;process-wide&quot; requirement is no longer enough; introduce persistent storage (DB sequence, Snowflake-style ID generator).</p><hr><h2 id="simple-factory" tabindex="-1">Simple Factory <a class="header-anchor" href="#simple-factory" aria-label="Permalink to &quot;Simple Factory&quot;">​</a></h2><h3 id="scenario-1-mdash-notification-dispatcher" tabindex="-1">Scenario 1 — Notification dispatcher <a class="header-anchor" href="#scenario-1-mdash-notification-dispatcher" aria-label="Permalink to &quot;Scenario 1 &amp;mdash; Notification dispatcher&quot;">​</a></h3><p>The product team wants to send notifications via email, SMS, or push, chosen by a string in user preferences (<code>&quot;email&quot;</code>, <code>&quot;sms&quot;</code>, <code>&quot;push&quot;</code>).</p><p><strong>Decision:</strong> Simple Factory, Strategy, or Registry?</p><p><strong>Consider:</strong></p><ul><li>The choice is <em>runtime-determined</em> from user data.</li><li>Adding a new channel (e.g., WhatsApp) is a likely future change.</li><li>A switch-on-string scattered everywhere is the smell to avoid.</li></ul><p><strong>Suggested approach:</strong> <strong>Simple Factory</strong> centralises the switch-on-string in one place. <strong>Better in a DI codebase</strong>: a <code>Map&lt;String, NotificationSender&gt;</code> registry populated by Spring; <code>Map.get(channel)</code> replaces the switch and adding a new sender requires zero changes to existing code (OCP). Simple Factory is the right <em>step zero</em>; the registry is the step one in any non-trivial system.</p><h3 id="scenario-2-mdash-document-parser-by-file-extension" tabindex="-1">Scenario 2 — Document parser by file extension <a class="header-anchor" href="#scenario-2-mdash-document-parser-by-file-extension" aria-label="Permalink to &quot;Scenario 2 &amp;mdash; Document parser by file extension&quot;">​</a></h3><p>A document-processing service receives uploaded files and parses them based on extension (<code>.pdf</code>, <code>.docx</code>, <code>.csv</code>).</p><p><strong>Decision:</strong> Simple Factory or Factory Method?</p><p><strong>Consider:</strong></p><ul><li>The decision is purely &quot;which parser, given an extension&quot;.</li><li>Each parser does completely different work internally.</li><li>The extension is data, not a class hierarchy.</li></ul><p><strong>Suggested approach:</strong> <strong>Simple Factory or registry</strong>. The selection is keyed by data (extension string), so a <code>Map&lt;String, Parser&gt;</code> in a <code>ParserRegistry</code> works well. Factory Method would be wrong here — no inheritance hierarchy is involved on the <em>caller</em> side.</p><h3 id="scenario-3-mdash-discount-calculator-by-customer-tier" tabindex="-1">Scenario 3 — Discount calculator by customer tier <a class="header-anchor" href="#scenario-3-mdash-discount-calculator-by-customer-tier" aria-label="Permalink to &quot;Scenario 3 &amp;mdash; Discount calculator by customer tier&quot;">​</a></h3><p>E-commerce checkout applies a discount strategy based on customer tier (free, gold, platinum, vip).</p><p><strong>Decision:</strong> Simple Factory or Strategy?</p><p><strong>Consider:</strong></p><ul><li>Each tier has <em>different logic</em> (percentage, flat amount, none).</li><li>Tier may change as the customer transacts (within a single checkout flow even).</li><li>Adding a new tier should require minimal change.</li></ul><p><strong>Suggested approach:</strong> <strong>Strategy + Registry.</strong> This is precisely the case where &quot;factory&quot; and &quot;strategy&quot; blur — both involve picking an implementation by a key. The Strategy framing is more accurate because the <em>behaviour</em> varies (calculation), not the <em>type</em> (the result is always a discount). A registry lookup retrieves the right strategy.</p><h3 id="scenario-4-mdash-http-client-picker-by-environment" tabindex="-1">Scenario 4 — HTTP client picker by environment <a class="header-anchor" href="#scenario-4-mdash-http-client-picker-by-environment" aria-label="Permalink to &quot;Scenario 4 &amp;mdash; HTTP client picker by environment&quot;">​</a></h3><p>Tests need a mock HTTP client; staging needs a recording client; production needs a real client.</p><p><strong>Decision:</strong> Simple Factory or DI?</p><p><strong>Consider:</strong></p><ul><li>The choice is <em>deployment-time</em>, not runtime.</li><li>Tests must control which client is used.</li><li>Production code shouldn&#39;t know there&#39;s a mock alternative.</li></ul><p><strong>Suggested approach:</strong> <strong>Dependency Injection</strong> — configure the right bean per environment via Spring profiles or constructor wiring in a manual setup. A Simple Factory with a <code>if (env == &quot;test&quot;)</code> branch in production code is exactly the smell DI removes.</p><h3 id="scenario-5-mdash-payment-provider-by-country" tabindex="-1">Scenario 5 — Payment provider by country <a class="header-anchor" href="#scenario-5-mdash-payment-provider-by-country" aria-label="Permalink to &quot;Scenario 5 &amp;mdash; Payment provider by country&quot;">​</a></h3><p>A payment service routes through Razorpay for India, Stripe for the US, Adyen for Europe.</p><p><strong>Decision:</strong> Simple Factory, Registry, or Strategy?</p><p><strong>Consider:</strong></p><ul><li>The route is determined by a transaction&#39;s country code.</li><li>Each provider has wildly different API shapes — the abstraction over them needs design.</li><li>New providers are added regularly as the company expands.</li></ul><p><strong>Suggested approach:</strong> <strong>Registry</strong> keyed by country code, with each <code>PaymentProvider</code> implementation as a Spring bean. Behind the registry, providers conform to a common <code>PaymentProvider</code> interface (Strategy shape). The combination is &quot;Strategy + Registry&quot; — Simple Factory would work for the initial version but creates an editing-the-factory problem every time a provider is added.</p><hr><h2 id="factory-method-gof" tabindex="-1">Factory Method (GoF) <a class="header-anchor" href="#factory-method-gof" aria-label="Permalink to &quot;Factory Method (GoF)&quot;">​</a></h2><h3 id="scenario-1-mdash-hiring-pipeline-per-role" tabindex="-1">Scenario 1 — Hiring pipeline per role <a class="header-anchor" href="#scenario-1-mdash-hiring-pipeline-per-role" aria-label="Permalink to &quot;Scenario 1 &amp;mdash; Hiring pipeline per role&quot;">​</a></h3><p>You&#39;re building an HR system where each role (Android, Backend, iOS, ML) has the same five-step onboarding template, but each step&#39;s specifics differ per role (which laptop, which email group, which Slack channel).</p><p><strong>Decision:</strong> Factory Method or Simple Factory?</p><p><strong>Consider:</strong></p><ul><li>The <em>algorithm</em> (the five steps) is shared across roles.</li><li>The <em>one varying thing</em> per step is different per role.</li><li>New roles arrive periodically.</li></ul><p><strong>Suggested approach:</strong> <strong>Factory Method.</strong> The shared algorithm lives in an abstract base class as a <code>final</code> template method; each subclass overrides hooks for &quot;create developer&quot; and any role-specific bits. This is exactly the shape in <code>creational/factory/factory_method/</code>. Simple Factory wouldn&#39;t work because the <em>algorithm</em> is the part being shared; Simple Factory only handles object construction.</p><h3 id="scenario-2-mdash-ui-form-rendering-per-device" tabindex="-1">Scenario 2 — UI form rendering per device <a class="header-anchor" href="#scenario-2-mdash-ui-form-rendering-per-device" aria-label="Permalink to &quot;Scenario 2 &amp;mdash; UI form rendering per device&quot;">​</a></h3><p>A mobile app and a web app share the same form-rendering algorithm: validate, layout, render fields, submit. The rendering of each field type differs per device (mobile uses native widgets, web uses HTML).</p><p><strong>Decision:</strong> Factory Method or Abstract Factory?</p><p><strong>Consider:</strong></p><ul><li>One algorithm, many widget types per device.</li><li>&quot;Mobile&quot; and &quot;web&quot; are platforms; widgets within them must match.</li></ul><p><strong>Suggested approach:</strong> <strong>Abstract Factory</strong> — the family is &quot;all the widgets for this platform&quot; (button, input, dropdown, etc.). Factory Method would only work if each form had <em>one</em> product to vary, but a form has many widgets that all need to match the platform.</p><h3 id="scenario-3-mdash-test-fixture-builders-per-test-type" tabindex="-1">Scenario 3 — Test fixture builders per test type <a class="header-anchor" href="#scenario-3-mdash-test-fixture-builders-per-test-type" aria-label="Permalink to &quot;Scenario 3 &amp;mdash; Test fixture builders per test type&quot;">​</a></h3><p>Integration tests need a database fixture; unit tests need an in-memory fixture; performance tests need a load-pre-populated fixture. Each test base class&#39;s <code>setUp()</code> calls <code>createFixture()</code> to get its fixture.</p><p><strong>Decision:</strong> Factory Method?</p><p><strong>Consider:</strong></p><ul><li><code>setUp()</code> is a fixed sequence of steps every test type follows.</li><li>Each test type provides its own fixture creation.</li><li>No registry / runtime selection needed — the test type is the test class.</li></ul><p><strong>Suggested approach:</strong> <strong>Factory Method.</strong> Classic textbook fit: an abstract <code>IntegrationTestBase</code> with <code>setUp()</code> template method, <code>createFixture()</code> as the abstract hook. Each concrete test class overrides the hook.</p><h3 id="scenario-4-mdash-game-enemy-spawning-per-level" tabindex="-1">Scenario 4 — Game enemy spawning per level <a class="header-anchor" href="#scenario-4-mdash-game-enemy-spawning-per-level" aria-label="Permalink to &quot;Scenario 4 &amp;mdash; Game enemy spawning per level&quot;">​</a></h3><p>A platform game spawns different enemies per level. Each level shares the spawning algorithm (find spawn point, create enemy, place, register with AI system) but spawns different enemy types.</p><p><strong>Decision:</strong> Factory Method or Strategy?</p><p><strong>Consider:</strong></p><ul><li>Levels are coded as concrete classes (Level1, Level2, ...).</li><li>The algorithm is identical; only &quot;what enemy&quot; differs.</li></ul><p><strong>Suggested approach:</strong> <strong>Factory Method.</strong> Each level extends a <code>LevelBase</code> whose <code>spawnEnemies()</code> template method calls an abstract <code>createEnemy()</code> hook. Strategy would also work but typically Strategy is used when the <em>behaviour to vary</em> is plug-and-play at the call site; here the level <em>is</em> the variation.</p><h3 id="scenario-5-mdash-connection-retry-policy-per-service" tabindex="-1">Scenario 5 — Connection retry policy per service <a class="header-anchor" href="#scenario-5-mdash-connection-retry-policy-per-service" aria-label="Permalink to &quot;Scenario 5 &amp;mdash; Connection retry policy per service&quot;">​</a></h3><p>A microservice client library wants the same retry algorithm (try, on failure compute backoff, sleep, retry, give up) but each consuming service might have its own backoff curve.</p><p><strong>Decision:</strong> Factory Method or Strategy?</p><p><strong>Consider:</strong></p><ul><li>The algorithm is shared.</li><li>The <em>one varying thing</em> (backoff curve) is small and self-contained.</li><li>Consumers want to plug in a curve at call site, not subclass.</li></ul><p><strong>Suggested approach:</strong> <strong>Strategy.</strong> When the variance is one method&#39;s worth of logic and consumers want runtime substitution rather than subclassing, Strategy beats Factory Method. Factory Method is the right shape when you have a <em>type-shaped</em> variation (a whole subclass exists).</p><hr><h2 id="builder" tabindex="-1">Builder <a class="header-anchor" href="#builder" aria-label="Permalink to &quot;Builder&quot;">​</a></h2><h3 id="scenario-1-mdash-http-request-with-many-optional-headers" tabindex="-1">Scenario 1 — HTTP request with many optional headers <a class="header-anchor" href="#scenario-1-mdash-http-request-with-many-optional-headers" aria-label="Permalink to &quot;Scenario 1 &amp;mdash; HTTP request with many optional headers&quot;">​</a></h3><p>You&#39;re writing an HTTP client wrapper. A request has a URL (required), a method (required), and 0–N optional headers, query params, body, timeouts, retry policy, etc.</p><p><strong>Decision:</strong> Builder, telescoping constructors, or JavaBeans setters?</p><p><strong>Consider:</strong></p><ul><li>Many optional fields.</li><li>Want immutability for thread safety (multiple threads share the same <code>HttpRequest</code>).</li><li>Validation needed: timeout &gt; 0, URL non-blank, etc.</li></ul><p><strong>Suggested approach:</strong> <strong>Builder, EJ Item 2 style.</strong> This is the canonical fit. Java&#39;s own <code>HttpRequest.newBuilder()</code> is exactly this. Required fields in the Builder constructor; optional fields as fluent setters; validation in <code>build()</code>.</p><h3 id="scenario-2-mdash-insurance-policy-with-cross-field-validation" tabindex="-1">Scenario 2 — Insurance policy with cross-field validation <a class="header-anchor" href="#scenario-2-mdash-insurance-policy-with-cross-field-validation" aria-label="Permalink to &quot;Scenario 2 &amp;mdash; Insurance policy with cross-field validation&quot;">​</a></h3><p>An insurance product has dozens of fields with rules like &quot;if <code>coverageType == FULL</code>, <code>deductible</code> is required&quot; and &quot;totalPremium = basePremium + addOns.sum()&quot;.</p><p><strong>Decision:</strong> Builder, or constructor with all fields?</p><p><strong>Consider:</strong></p><ul><li>Cross-field invariants must hold <em>only after</em> all fields are set.</li><li>Many fields, several optional.</li><li>Validation should happen at one point in time.</li></ul><p><strong>Suggested approach:</strong> <strong>Builder.</strong> The cross-field invariant rules can only be checked when all fields have their final values — that&#39;s exactly what <code>build()</code> enables. A constructor with 30 parameters is unreadable, and JavaBeans setters leave the policy in a half-validated state until you remember to call <code>validate()</code> (which nobody does).</p><h3 id="scenario-3-mdash-test-data-factories" tabindex="-1">Scenario 3 — Test data factories <a class="header-anchor" href="#scenario-3-mdash-test-data-factories" aria-label="Permalink to &quot;Scenario 3 &amp;mdash; Test data factories&quot;">​</a></h3><p>Your tests need to construct domain objects (<code>User</code>, <code>Order</code>, <code>Invoice</code>) with sensible defaults but the ability to override one or two fields per test (&quot;user with admin role&quot;, &quot;order with status = REFUNDED&quot;).</p><p><strong>Decision:</strong> Builder, copy constructors, or test data builders?</p><p><strong>Consider:</strong></p><ul><li>95% of fields are the same default in most tests.</li><li>Each test wants to override one or two specific fields.</li><li>Tests should remain readable: <code>givenAnAdminUser()</code> is better than constructor with 12 args.</li></ul><p><strong>Suggested approach:</strong> <strong>Test data builder pattern</strong> — same shape as production Builder but with sensible defaults pre-filled, exposing setters only for the fields tests typically want to vary. This is one of Builder&#39;s most underrated production uses.</p><h3 id="scenario-4-mdash-email-message-with-optional-attachments-cc-bcc" tabindex="-1">Scenario 4 — Email message with optional attachments, cc, bcc <a class="header-anchor" href="#scenario-4-mdash-email-message-with-optional-attachments-cc-bcc" aria-label="Permalink to &quot;Scenario 4 &amp;mdash; Email message with optional attachments, cc, bcc&quot;">​</a></h3><p>An email-sending service needs to construct messages with <code>to</code> (required), <code>subject</code> (required), <code>body</code> (required), and <code>cc</code>, <code>bcc</code>, <code>attachments</code> (each optional, possibly multiple).</p><p><strong>Decision:</strong> Builder or constructor overloads?</p><p><strong>Consider:</strong></p><ul><li>Three required fields, three optional fields, two of which take collections.</li><li>Adding a new optional field (<code>replyTo</code>?) shouldn&#39;t break call sites.</li></ul><p><strong>Suggested approach:</strong> <strong>Builder</strong> — the required fields go in the Builder constructor; the collection-valued optional fields get fluent <code>addCc(String)</code> / <code>addBcc(String)</code> / <code>addAttachment(File)</code> methods that internally accumulate. Adding a new optional field is a one-line change with no impact on existing call sites.</p><h3 id="scenario-5-mdash-sql-query-construction" tabindex="-1">Scenario 5 — SQL query construction <a class="header-anchor" href="#scenario-5-mdash-sql-query-construction" aria-label="Permalink to &quot;Scenario 5 &amp;mdash; SQL query construction&quot;">​</a></h3><p>A reporting tool needs to generate SQL queries with optional WHERE clauses, joins, group-by, having, order-by, limit.</p><p><strong>Decision:</strong> Builder, fluent string concatenation, or a query DSL?</p><p><strong>Consider:</strong></p><ul><li>Composition order doesn&#39;t always matter; some clauses are independent (where vs join).</li><li>The output is text, not a structured object.</li><li>Complexity grows fast: subqueries, parameter binding.</li></ul><p><strong>Suggested approach:</strong> <strong>Builder</strong> for simple needs (SELECT/FROM/WHERE/ORDER BY) — fluent setters that accumulate into a <code>StringBuilder</code>. For non-trivial reporting, use a real DSL (jOOQ, QueryDSL); rolling your own SQL builder is a long-tail tar pit.</p><hr><h2 id="static-factory-methods-ej-item-1" tabindex="-1">Static Factory Methods (EJ Item 1) <a class="header-anchor" href="#static-factory-methods-ej-item-1" aria-label="Permalink to &quot;Static Factory Methods (EJ Item 1)&quot;">​</a></h2><h3 id="scenario-1-mdash-money-value-class" tabindex="-1">Scenario 1 — Money value class <a class="header-anchor" href="#scenario-1-mdash-money-value-class" aria-label="Permalink to &quot;Scenario 1 &amp;mdash; Money value class&quot;">​</a></h3><p>You&#39;re modelling <code>Money</code> with amount and currency. You want <code>Money.usd(100)</code>, <code>Money.eur(200)</code>, <code>Money.fromString(&quot;$10.50&quot;)</code>, <code>Money.zero(currency)</code>.</p><p><strong>Decision:</strong> Constructor only, or static factory methods?</p><p><strong>Consider:</strong></p><ul><li>Construction strategies need <em>names</em> (USD vs EUR can&#39;t be distinguished by an <code>int</code> overload).</li><li>A <code>zero</code> of any currency is a frequent, identical value — cache it.</li><li>Parsing a string is a different operation than passing amount + currency.</li></ul><p><strong>Suggested approach:</strong> <strong>Static factory methods.</strong> This is the textbook fit for benefit #1 (names) and benefit #2 (caching of common values). The constructor is <code>private</code>; named factories <code>usd</code>, <code>eur</code>, <code>fromString</code>, <code>zero</code> cover the construction strategies.</p><h3 id="scenario-2-mdash-returning-a-private-subtype" tabindex="-1">Scenario 2 — Returning a private subtype <a class="header-anchor" href="#scenario-2-mdash-returning-a-private-subtype" aria-label="Permalink to &quot;Scenario 2 &amp;mdash; Returning a private subtype&quot;">​</a></h3><p>A <code>Cache</code> library wants <code>Cache.bounded(maxSize)</code>, <code>Cache.unbounded()</code>, <code>Cache.weakKey()</code>. Each returns a different internal class but callers should only see <code>Cache</code>.</p><p><strong>Decision:</strong> Static factory methods, or expose the internal classes?</p><p><strong>Consider:</strong></p><ul><li>Hiding the internal class is the whole point.</li><li>Callers should code against <code>Cache</code>, not <code>BoundedCache</code> etc.</li></ul><p><strong>Suggested approach:</strong> <strong>Static factory methods, returning the abstract type.</strong> Benefit #3 (returning subtype) is the headline. The internal classes can be <code>package-private</code> or <code>private</code> nested classes, never exposed.</p><h3 id="scenario-3-mdash-switching-algorithm-based-on-input-size" tabindex="-1">Scenario 3 — Switching algorithm based on input size <a class="header-anchor" href="#scenario-3-mdash-switching-algorithm-based-on-input-size" aria-label="Permalink to &quot;Scenario 3 &amp;mdash; Switching algorithm based on input size&quot;">​</a></h3><p>You&#39;re writing a sort utility where small inputs go through insertion sort and large inputs through merge sort. The caller shouldn&#39;t know.</p><p><strong>Decision:</strong> Static factory method or two separate utilities?</p><p><strong>Consider:</strong></p><ul><li>The caller knows nothing about input size strategy — they just want it sorted.</li><li>Picking the right algorithm should be the utility&#39;s job.</li></ul><p><strong>Suggested approach:</strong> <strong>Static factory method that returns a type-erased abstract.</strong> <code>Sorter.optimalFor(input)</code> returns a <code>Sorter</code> instance whose concrete class is chosen by input size. Benefit #4 (returned class varies by input).</p><h3 id="scenario-4-mdash-plugin-discovery" tabindex="-1">Scenario 4 — Plugin discovery <a class="header-anchor" href="#scenario-4-mdash-plugin-discovery" aria-label="Permalink to &quot;Scenario 4 &amp;mdash; Plugin discovery&quot;">​</a></h3><p>A logging library needs to find logging providers (Logback, Log4j, JUL) at runtime based on what&#39;s on the classpath.</p><p><strong>Decision:</strong> Static factory method or a registration API?</p><p><strong>Consider:</strong></p><ul><li>The caller doesn&#39;t know which logging provider exists.</li><li>The provider may not even exist when the library is compiled.</li></ul><p><strong>Suggested approach:</strong> <strong>Static factory method backed by <code>ServiceLoader</code></strong> — benefit #5 (returned class need not exist at compile time). <code>LoggerFactory.getLogger(name)</code> looks up an SPI provider at runtime; SLF4J does this exactly.</p><h3 id="scenario-5-mdash-disambiguating-constructor-overloads" tabindex="-1">Scenario 5 — Disambiguating constructor overloads <a class="header-anchor" href="#scenario-5-mdash-disambiguating-constructor-overloads" aria-label="Permalink to &quot;Scenario 5 &amp;mdash; Disambiguating constructor overloads&quot;">​</a></h3><p>A <code>Duration</code> class can be constructed from milliseconds, seconds, minutes, or a parsed string. Each takes a long.</p><p><strong>Decision:</strong> Static factory or constructor overloads?</p><p><strong>Consider:</strong></p><ul><li>Multiple <code>Duration(long)</code> overloads collide on signature.</li><li>The caller&#39;s intent (&quot;ten seconds&quot;) is lost in <code>new Duration(10)</code>.</li></ul><p><strong>Suggested approach:</strong> <strong>Static factory methods</strong> following the convention: <code>Duration.ofMillis(10)</code>, <code>Duration.ofSeconds(10)</code>, <code>Duration.ofMinutes(10)</code>, <code>Duration.parse(&quot;PT10S&quot;)</code>. Java&#39;s actual <code>java.time.Duration</code> is exactly this. Benefit #1 (names disambiguate).</p><hr><h2 id="abstract-factory" tabindex="-1">Abstract Factory <a class="header-anchor" href="#abstract-factory" aria-label="Permalink to &quot;Abstract Factory&quot;">​</a></h2><h3 id="scenario-1-mdash-multi-platform-ui-toolkit" tabindex="-1">Scenario 1 — Multi-platform UI toolkit <a class="header-anchor" href="#scenario-1-mdash-multi-platform-ui-toolkit" aria-label="Permalink to &quot;Scenario 1 &amp;mdash; Multi-platform UI toolkit&quot;">​</a></h3><p>A cross-platform IDE renders the same UI on macOS, Windows, and Linux. Each platform&#39;s button, dropdown, and tab look different, but a button and a tab on the same platform must visually match.</p><p><strong>Decision:</strong> Factory Method, Abstract Factory, or Strategy?</p><p><strong>Consider:</strong></p><ul><li>Multiple product types per platform (button, dropdown, tab, ...).</li><li>Platform-internal consistency is a hard requirement — mismatched widgets break the UI.</li></ul><p><strong>Suggested approach:</strong> <strong>Abstract Factory.</strong> <code>UIFactory</code> declares <code>createButton</code>, <code>createDropdown</code>, <code>createTab</code>; <code>MacUIFactory</code>, <code>WindowsUIFactory</code>, <code>LinuxUIFactory</code> implement them. The type system prevents mixing widgets across platforms.</p><h3 id="scenario-2-mdash-multi-tenant-saas" tabindex="-1">Scenario 2 — Multi-tenant SaaS <a class="header-anchor" href="#scenario-2-mdash-multi-tenant-saas" aria-label="Permalink to &quot;Scenario 2 &amp;mdash; Multi-tenant SaaS&quot;">​</a></h3><p>A B2B SaaS app needs different <em>theme</em> (CSS, logo, colour palette), <em>data store</em> (each customer&#39;s DB shard), and <em>feature flags</em> per tenant.</p><p><strong>Decision:</strong> Abstract Factory or DI with tenant-scoped beans?</p><p><strong>Consider:</strong></p><ul><li>Each tenant has many &quot;products&quot; (theme, data store, feature flags) that must match.</li><li>The tenant axis is a runtime decision per request.</li></ul><p><strong>Suggested approach:</strong> <strong>DI with tenant-scoped beans</strong> is the production answer. The Abstract Factory shape (<code>TenantFactory.createTheme()</code>, <code>TenantFactory.createDataStore()</code>, etc.) is conceptually right and worth knowing, but in a Spring app the DI container handles per-tenant scoping more cleanly than hand-rolled factories.</p><h3 id="scenario-3-mdash-jdbc-drivers" tabindex="-1">Scenario 3 — JDBC drivers <a class="header-anchor" href="#scenario-3-mdash-jdbc-drivers" aria-label="Permalink to &quot;Scenario 3 &amp;mdash; JDBC drivers&quot;">​</a></h3><p>You&#39;re writing a database client that supports MySQL, Postgres, and Oracle. Each provides a different <code>Connection</code>, <code>Statement</code>, and <code>ResultSet</code> implementation, but they belong together (a Postgres <code>Statement</code> doesn&#39;t work on a MySQL <code>Connection</code>).</p><p><strong>Decision:</strong> Abstract Factory or Factory Method?</p><p><strong>Consider:</strong></p><ul><li>Multiple coordinated products per vendor.</li><li>Within one vendor, all artefacts must come from the same source.</li></ul><p><strong>Suggested approach:</strong> <strong>Abstract Factory.</strong> This is JDBC&#39;s actual design: <code>Driver</code> is the abstract factory, <code>Connection</code> is created by it, <code>Statement</code>/<code>ResultSet</code> are produced from <code>Connection</code> (sub-factory step). The &quot;family must match&quot; requirement is exactly the pattern&#39;s headline.</p><h3 id="scenario-4-mdash-game-asset-bundle-per-regional-theme" tabindex="-1">Scenario 4 — Game asset bundle per regional theme <a class="header-anchor" href="#scenario-4-mdash-game-asset-bundle-per-regional-theme" aria-label="Permalink to &quot;Scenario 4 &amp;mdash; Game asset bundle per regional theme&quot;">​</a></h3><p>A mobile game has Halloween, Christmas, and Valentine&#39;s themes. Each theme replaces the title screen graphics, sound effects, sprites, and music.</p><p><strong>Decision:</strong> Abstract Factory or asset registry?</p><p><strong>Consider:</strong></p><ul><li>Multiple coordinated assets per theme.</li><li>Theme is a runtime config — chosen on app launch.</li><li>Adding a new theme should be additive.</li></ul><p><strong>Suggested approach:</strong> <strong>Abstract Factory.</strong> <code>ThemeFactory</code> interface; <code>HalloweenThemeFactory</code>, <code>ChristmasThemeFactory</code>, etc., each producing matching <code>TitleGraphics</code>, <code>SoundPack</code>, <code>SpriteSet</code>, <code>MusicTrack</code>. The runtime &quot;load theme&quot; step picks the factory once; everything downstream gets matching assets.</p><h3 id="scenario-5-mdash-test-environment-fixtures-database-cache-queue-storage" tabindex="-1">Scenario 5 — Test environment fixtures (database + cache + queue + storage) <a class="header-anchor" href="#scenario-5-mdash-test-environment-fixtures-database-cache-queue-storage" aria-label="Permalink to &quot;Scenario 5 &amp;mdash; Test environment fixtures (database + cache + queue + storage)&quot;">​</a></h3><p>Integration tests need a coordinated set of test infrastructure: in-memory DB + in-memory cache + in-memory queue + temp file storage. Production uses real DB + Redis + Kafka + S3. The test-vs-prod choice is environment-driven.</p><p><strong>Decision:</strong> Abstract Factory or DI profile?</p><p><strong>Consider:</strong></p><ul><li>Multiple coordinated infrastructure clients.</li><li>The choice is environment-time, not runtime per-call.</li><li>All four artefacts must &quot;match&quot; — if you mock one and not the others, integration tests get weird.</li></ul><p><strong>Suggested approach:</strong> <strong>DI profile-based wiring</strong> in production code; <strong>Abstract Factory</strong> is a defensible alternative if you don&#39;t have a DI container. Spring profiles (<code>@Profile(&quot;test&quot;)</code> vs <code>@Profile(&quot;prod&quot;)</code>) effectively <em>are</em> an abstract factory at the DI-config layer — you pick the profile, you get a coordinated set of beans.</p><hr><h2 id="cross-pattern-decision-questions" tabindex="-1">Cross-pattern decision questions <a class="header-anchor" href="#cross-pattern-decision-questions" aria-label="Permalink to &quot;Cross-pattern decision questions&quot;">​</a></h2><p>Synthesis exercises — given a scenario, decide which of multiple patterns fits and why.</p><h3 id="q1-mdash-i-have-many-optional-fields-and-need-an-immutable-result" tabindex="-1">Q1 — &quot;I have many optional fields and need an immutable result&quot; <a class="header-anchor" href="#q1-mdash-i-have-many-optional-fields-and-need-an-immutable-result" aria-label="Permalink to &quot;Q1 &amp;mdash; &quot;I have many optional fields and need an immutable result&quot;&quot;">​</a></h3><p>Possible candidates: Builder, Static Factory Methods, telescoping constructors.</p><p><strong>Resolution:</strong></p><ul><li><em>4+ optional fields, immutability, validation</em> → <strong>Builder.</strong></li><li><em>2–3 optional fields, simple construction</em> → <strong>Static factory methods</strong> with named overloads (<code>of</code>, <code>from</code>).</li><li><em>Always-required fields only</em> → plain constructor.</li></ul><h3 id="q2-mdash-i-want-one-logical-instance-shared-everywhere" tabindex="-1">Q2 — &quot;I want one logical instance shared everywhere&quot; <a class="header-anchor" href="#q2-mdash-i-want-one-logical-instance-shared-everywhere" aria-label="Permalink to &quot;Q2 &amp;mdash; &quot;I want one logical instance shared everywhere&quot;&quot;">​</a></h3><p>Possible candidates: Singleton, DI singleton scope, Static factory methods (cached).</p><p><strong>Resolution:</strong></p><ul><li><em>In a DI codebase</em> → <strong>DI singleton-scoped bean.</strong> Don&#39;t write <code>getInstance()</code>.</li><li><em>In plain Java with no framework</em> → <strong>Bill Pugh holder Singleton</strong> (thread-safe, lazy, simple).</li><li><em>Cached values of an immutable type</em> → <strong>Static factory method with caching</strong> (<code>Boolean.valueOf</code>, <code>Integer.valueOf</code>).</li></ul><h3 id="q3-mdash-i-need-to-construct-one-of-several-similar-things-based-on-input" tabindex="-1">Q3 — &quot;I need to construct one of several similar things based on input&quot; <a class="header-anchor" href="#q3-mdash-i-need-to-construct-one-of-several-similar-things-based-on-input" aria-label="Permalink to &quot;Q3 &amp;mdash; &quot;I need to construct one of several similar things based on input&quot;&quot;">​</a></h3><p>Possible candidates: Simple Factory, Factory Method, Abstract Factory, Strategy + Registry.</p><p><strong>Resolution:</strong></p><ul><li><em>Selection by string/enum, one product type</em> → <strong>Simple Factory or Registry.</strong></li><li><em>Algorithm shared across subclasses, one varying product per subclass</em> → <strong>Factory Method.</strong></li><li><em>Family of coordinated products that must match</em> → <strong>Abstract Factory.</strong></li><li><em>Behaviour swap, not type swap</em> → <strong>Strategy + Registry.</strong></li></ul><h3 id="q4-mdash-i-need-to-call-alternative-construction-strategies-on-the-same-class" tabindex="-1">Q4 — &quot;I need to call alternative construction strategies on the same class&quot; <a class="header-anchor" href="#q4-mdash-i-need-to-call-alternative-construction-strategies-on-the-same-class" aria-label="Permalink to &quot;Q4 &amp;mdash; &quot;I need to call alternative construction strategies on the same class&quot;&quot;">​</a></h3><p>Possible candidates: Static factory methods, Builder.</p><p><strong>Resolution:</strong></p><ul><li><em>Multiple ways to construct the same object, each with a meaningful name</em> → <strong>Static factory methods</strong> (<code>Money.usd</code>, <code>Money.eur</code>, <code>Money.fromString</code>).</li><li><em>One construction with many optional knobs</em> → <strong>Builder.</strong></li><li>These can coexist in the same class — static factories cover the common cases, the Builder covers the long tail.</li></ul><h3 id="q5-mdash-i-have-a-class-with-internal-state-that-varies-but-the-algorithm-is-shared" tabindex="-1">Q5 — &quot;I have a class with internal state that varies but the algorithm is shared&quot; <a class="header-anchor" href="#q5-mdash-i-have-a-class-with-internal-state-that-varies-but-the-algorithm-is-shared" aria-label="Permalink to &quot;Q5 &amp;mdash; &quot;I have a class with internal state that varies but the algorithm is shared&quot;&quot;">​</a></h3><p>Possible candidates: Factory Method, Template Method, Strategy.</p><p><strong>Resolution:</strong></p><ul><li><em>The algorithm is shared as a <code>final</code> method that calls hooks</em> → <strong>Template Method</strong> (Factory Method is its construction-flavoured cousin).</li><li><em>The algorithm needs runtime substitution by the caller</em> → <strong>Strategy.</strong></li></ul><hr><h2 id="notes-on-using-these-scenarios" tabindex="-1">Notes on using these scenarios <a class="header-anchor" href="#notes-on-using-these-scenarios" aria-label="Permalink to &quot;Notes on using these scenarios&quot;">​</a></h2><ul><li><strong>Don&#39;t memorise.</strong> The point is to internalise the <em>trade-offs</em> — immutability, OCP, family-coordination, runtime selection — not which scenario maps to which pattern.</li><li><strong>Question the suggested approach.</strong> Several scenarios admit multiple defensible answers. If you reasoned to a different pattern with a justification grounded in the trade-offs, you&#39;ve understood the lesson.</li><li><strong>Look at real codebases for variants.</strong> When you see Spring&#39;s <code>BeanFactory</code>, JDBC&#39;s driver loading, or <code>Stream.builder()</code>, ask: which pattern is this, and which trade-off is it optimising for?</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><code>design_patterns/creational/CreationalPatternsRoadmap.md</code> — the order in which the patterns were learned.</li><li><code>design_patterns/creational/builder/Builder.md</code> — cross-cutting overview of the four builder variants.</li><li><code>design_patterns/creational/factory/Factory.md</code> — Simple Factory vs Factory Method.</li><li><code>design_patterns/creational/abstract_factory/AbstractFactory.md</code> — the four discussion learnings from the Abstract Factory build.</li><li><code>study_plan/deep_dives/PatternSelectionExercise.md</code> — deeper, single-domain exercise on Strategy / Registry / DI for the &quot;one HR, many factories&quot; problem.</li><li><code>study_plan/deep_dives/DesignThinkingProcess.md</code> — the meta-process behind every scenario in this doc (pain → responsibilities → vary vs. stay → arrows → skeleton → verify).</li></ul>',226)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
